    Arrays.fill(memo, -1);
    return count(n, memo);
  }

  private int count(int nodes, int[] memo) {
    if (nodes <= 1) return 1;
    if (memo[nodes] != -1) return memo[nodes];
    int total = 0;
    for (int root = 1; root <= nodes; root++) {
      total += count(root - 1, memo) * count(nodes - root, memo);
    }
    memo[nodes] = total;
    return total;
  }
}

